                        <ThumbsUp className="w-3 h-3" />
                        {style.label}
                      </span>
                      <span className="text-[11px] text-[var(--color-fg-faint)]">KI-Bewertung</span>
                    </div>
                    {/* Strengths */}
                    {rating.strong?.length > 0 && (
                      <ul className="flex flex-col gap-1.5">
                        {rating.strong.map((s, i) => (
