/**
 * JobsPage — Meine Stellen.
 * Grouped by status: Im Gespräch → Angebot → Beworben → Gemerkt → Erledigt (collapsible).
 */
export default function JobsPage() {
  const navigate = useNavigate();
  const qc = useQueryClient();

  const { data: savedJobs = [], isFetching: savedFetching } = useQuery({
    queryKey: ["jobs"],
    queryFn: () =>
      jobApi.list().then((r) => {
        const items = r.data?.items ?? r.data ?? [];
        saveStored("jobs", items);
        try { localStorage.setItem("jobs_ts", String(Date.now())); } catch { /* quota */ }
        return items;
      }),
    initialData: () => loadStored("jobs") || [],
    initialDataUpdatedAt: () => {
      try { return parseInt(localStorage.getItem("jobs_ts") || "0", 10); } catch { return 0; }
    },
    staleTime: 0,
    retry: 2,
  });

  const [mutedIds, setMutedIds] = useState(() => new Set(loadStored(MUTED_KEY) || []));
  useEffect(() => {
    saveStored(MUTED_KEY, Array.from(mutedIds));
  }, [mutedIds]);

  useEffect(() => {
    if (mutedIds.size === 0) return;
    const liveIds = new Set(savedJobs.map((j) => j.id));
    let dirty = false;
    const next = new Set();
    mutedIds.forEach((id) => {
      if (liveIds.has(id)) next.add(id);
      else dirty = true;
    });
    if (dirty) setMutedIds(next);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [savedJobs]);

  // ── Auto-remove expired bookmarked jobs ─────────────────────────────────────
  // Runs once per mount after the first real API fetch resolves.
  // Only removes "bookmarked" jobs (user has not yet acted) whose expires_at /
  // deadline is in the past. Applied / Gespräch / Angebot / Erledigt are
  // intentionally kept so the user can track their application outcomes.
  const expiredCleanupRef = useRef(false);
  useEffect(() => {
    if (savedFetching || savedJobs.length === 0 || expiredCleanupRef.current) return;
    expiredCleanupRef.current = true;

    const now = Date.now();
    const expired = savedJobs.filter((j) => {
      if (j.status !== "bookmarked") return false;
      const raw = j.expires_at || j.deadline;
      if (!raw) return false;
      const t = new Date(raw).getTime();
      return Number.isFinite(t) && t < now;
    });
    if (!expired.length) return;

    const ids = new Set(expired.map((e) => e.id));
    qc.setQueryData(["jobs"], (old = []) => old.filter((j) => !ids.has(j.id)));

    Promise.allSettled(expired.map((j) => jobApi.delete(j.id))).then(() => {
      const fresh = qc.getQueryData(["jobs"]) || [];
      saveStored("jobs", fresh);
    });

    const companies = [...new Set(expired.map((j) => j.company).filter(Boolean))].slice(0, 3);
    const noun = expired.length === 1 ? "Stelle" : "Stellen";
    const coStr = companies.length ? ` — ${companies.join(", ")}` : "";
    toast(`${expired.length} abgelaufene ${noun} entfernt${coStr}. Frist bereits vorbei.`, { duration: 7000 });
  }, [savedJobs, savedFetching, qc]);

  const [searchParams, setSearchParams] = useSearchParams();
  const [activeFilter, setActiveFilter] = useState(() => {
    const s = searchParams.get("status");
    return FILTER_CHIPS.some((c) => c.key === s) ? s : "alle";
  });

  // Group by status, sorted by most recently updated
  const [sortBy, setSortBy] = useState(() => {
    const s = searchParams.get("sort");
    return s === "score" ? "score" : "date";
  });

  const setFilter = (key) => {
    setActiveFilter(key);
    const next = new URLSearchParams(searchParams);
    if (key === "alle") next.delete("status");
    else next.set("status", key);
    setSearchParams(next, { replace: true });
  };

  const setSort = (s) => {
    setSortBy(s);
    const next = new URLSearchParams(searchParams);
    if (s === "date") next.delete("sort");
    else next.set("sort", s);
    setSearchParams(next, { replace: true });
  };

  const grouped = useMemo(() => {
    const out = { interviewing: [], offered: [], applied: [], bookmarked: [], rejected: [] };
    savedJobs.forEach((j) => {
      const key = j.status in out ? j.status : "bookmarked";
      out[key].push(j);
    });
    Object.values(out).forEach((arr) =>
      arr.sort((a, b) => {
        if (sortBy === "score") {
          const sa = b.match_score ?? -1;
          const sb = a.match_score ?? -1;
          return sa - sb;
        }
        const da = new Date(a.updated_at || a.created_at).getTime() || 0;
        const db = new Date(b.updated_at || b.created_at).getTime() || 0;
        return db - da;
      }),
    );
    return out;
  }, [savedJobs, sortBy]);

  const heute = useMemo(() => pickHeuteAction(savedJobs, mutedIds), [savedJobs, mutedIds]);

  const [sheetJob, setSheetJob] = useState(null);
  const closeSheet = () => setSheetJob(null);

  const statusMutation = useMutation({
    mutationFn: ({ jobId, status }) => jobApi.updateStatus(jobId, status),
    onMutate: async ({ jobId, status }) => {
      await qc.cancelQueries({ queryKey: ["jobs"] });
      const prev = qc.getQueryData(["jobs"]);
      qc.setQueryData(["jobs"], (old = []) =>
        old.map((j) => (j.id === jobId ? { ...j, status, updated_at: new Date().toISOString() } : j)),
      );
      return { prev };
    },
    onSuccess: (_data, variables) => {
      const msgs = {
        bookmarked: "Gespeichert. Bewirb dich, wenn es passt.",
        applied: "Beworben. Antworten dauern im Schnitt 8 Tage.",
        interviewing: "Im Gespräch. Bereite Fragen zum Unternehmen vor.",
        offered: "Angebot erhalten. Vergleiche die Konditionen in Ruhe.",
        rejected: "Erledigt. Nicht aufgeben — die nächste Stelle passt besser.",
      };
      toast.success(msgs[variables.status] || "Status aktualisiert");
    },
    onError: (err, _vars, ctx) => {
      qc.setQueryData(["jobs"], ctx?.prev);
      toast.error(getApiErrorMessage(err, "Status konnte nicht geändert werden"));
    },
  });

  const handleStatusPick = (status) => {
    if (!sheetJob) return;
    if (status !== sheetJob.status) statusMutation.mutate({ jobId: sheetJob.id, status });
    closeSheet();
  };

  const handleToggleMute = () => {
    if (!sheetJob) return;
    setMutedIds((prev) => {
      const next = new Set(prev);
      if (next.has(sheetJob.id)) next.delete(sheetJob.id);
      else next.add(sheetJob.id);
      return next;
    });
    closeSheet();
  };

  const scrollSaveRef = useRef(false);
  useEffect(() => {
    const savedY = sessionStorage.getItem("jobsPageScrollY");
    if (savedY) requestAnimationFrame(() => window.scrollTo({ top: parseInt(savedY, 10), behavior: "instant" }));
    return () => {
      if (scrollSaveRef.current) sessionStorage.setItem("jobsPageScrollY", String(window.scrollY));
    };
  }, []);

  const openJob = (jobId) => { scrollSaveRef.current = true; navigate(`/jobs/${jobId}`); };

  const total = savedJobs.length;
  const [showDone, setShowDone] = useState(false);

  const visibleGroups = activeFilter === "alle"
    ? STATUS_GROUPS
    : STATUS_GROUPS.filter((g) => g.key === activeFilter);

  const hasVisibleRejected = (activeFilter === "alle" || activeFilter === "rejected") && grouped.rejected.length > 0;
  const hasAnyVisible = visibleGroups.some((g) => grouped[g.key]?.length > 0)
    || (hasVisibleRejected && (showDone || activeFilter === "rejected"));

  return (
    <div className="flex flex-col gap-5 animate-slide-up">

      {/* ── Header ──────────────────────────────────────────────────── */}
      <header className="flex items-end justify-between gap-4">
        <div className="min-w-0">
          <h1 className="text-[28px] sm:text-[34px] font-semibold leading-[1.1] text-[var(--color-fg)]" style={{ letterSpacing: "-0.025em" }}>
            Stellen
          </h1>
          <p className="mt-1.5 text-[13px] text-[var(--color-fg-muted)]">
            {total === 0 ? "Speichere deine erste Stelle." : `${total} gespeichert`}
          </p>
        </div>
        <button
          type="button"
          onClick={() => navigate("/finden")}
          className="inline-flex items-center gap-1.5 px-3 py-[7px] rounded-lg text-[12.5px] font-semibold transition-all hover:-translate-y-px"
          style={{ background: "#7c7df0", color: "#fff", boxShadow: "0 0 0 1px rgba(124,125,240,.4), 0 4px 14px rgba(124,125,240,.25)" }}
        >
          <Plus className="w-3 h-3" />
          Neue Stelle
        </button>
      </header>

      {/* ── Near-capacity notice ──────────────────────────────────── */}
      {total >= 480 && total < 500 && (
        <div className="rounded-lg border border-[var(--color-warning)]/20 bg-[var(--color-warning-soft)] px-4 py-3 text-[12.5px] text-[var(--color-fg-muted)]">
          Deine Liste hat {total} Stellen. Bei 500 ist das Limit erreicht.
        </div>
      )}

      {/* ── Filter chips + sort toggle ───────────────────────────── */}
      {total > 0 && (
        <div className="flex items-center gap-2 flex-wrap">
          <div className="flex flex-wrap gap-1.5 flex-1">
            {FILTER_CHIPS.map(({ key, label, dot, activeBg, activeBorder }) => {
              const count = key === "alle" ? total : (grouped[key]?.length ?? 0);
              const isActive = activeFilter === key;
              return (
                <button
                  key={key}
                  type="button"
                  onClick={() => setFilter(key)}
                  className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11.5px] font-medium transition-all"
                  style={isActive
                    ? { background: activeBg, border: `1px solid ${activeBorder}`, color: C.ink }
                    : { background: "transparent", border: `1px solid ${C.lineSubtle}`, color: C.inkDim }}
                >
                  <span className="w-[5px] h-[5px] rounded-full flex-shrink-0" style={{ background: dot }} />
                  {label}
                  <span
                    className="text-[10.5px] font-semibold tabular-nums px-1 rounded"
                    style={{ background: isActive ? "rgba(255,255,255,0.08)" : C.surface3, color: isActive ? C.inkMuted : C.inkFaint }}
                  >{count}</span>
                </button>
              );
            })}
          </div>
          <button
            type="button"
            onClick={() => setSort(sortBy === "date" ? "score" : "date")}
            className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-medium transition-all flex-shrink-0"
            style={sortBy === "score"
              ? { background: "rgba(124,125,240,0.14)", border: "1px solid rgba(124,125,240,0.35)", color: "#a5b4fc" }
              : { background: "transparent", border: `1px solid ${C.lineSubtle}`, color: C.inkDim }}
          >
            <ArrowUpDown className="w-3 h-3" />
            {sortBy === "score" ? "Passung" : "Datum"}
          </button>
        </div>
      )}

      {/* ── Urgent card ─────────────────────────────────────────────── */}
      {heute ? <HeuteCard heute={heute} onOpen={openJob} /> : null}

      {/* ── Loading / Empty / Lists ─────────────────────────────────── */}
      {savedFetching && total === 0 ? (
        <RowSkeleton />
      ) : total === 0 ? (
        <EmptyState
          tone="subtle"
          title="Speichere eine Stelle, um sie hier zu sehen."
          description="Starte mit Empfehlungen oder einer eigenen Suche."
          icon={Sparkles}
          action={<Button onClick={() => navigate("/finden")}><Search className="w-3.5 h-3.5" />Stelle finden</Button>}
        />
      ) : (
        <div className="flex flex-col gap-5">

          {visibleGroups.map(({ key, label, dot }) => {
            const jobs = grouped[key];
            if (!jobs || jobs.length === 0) return null;
            return (
              <div key={key}>
                <SectionLabel label={label} count={jobs.length} dot={dot} />
                {jobs.map((job, i) => (
                  <ThreadRow
                    key={job.id}
                    job={job}
                    isFirst={i === 0}
                    muted={mutedIds.has(job.id)}
                    onOpen={() => openJob(job.id)}
                    onChangeStatus={() => setSheetJob(job)}
                  />
                ))}
              </div>
            );
          })}

          {(activeFilter === "alle" || activeFilter === "rejected") && grouped.rejected.length > 0 && (
            <div>
              <SectionLabel
                label="Erledigt"
                count={grouped.rejected.length}
                dot={C.inkFaint}
                collapsible={activeFilter === "alle"}
                collapsed={activeFilter === "alle" ? !showDone : false}
                onToggle={() => setShowDone((v) => !v)}
              />
              {(showDone || activeFilter === "rejected") && grouped.rejected.map((job, i) => (
                <ThreadRow
                  key={job.id}
                  job={job}
                  isFirst={i === 0}
                  muted={mutedIds.has(job.id)}
                  onOpen={() => openJob(job.id)}
                  onChangeStatus={() => setSheetJob(job)}
                />
              ))}
            </div>
          )}

          {!hasAnyVisible && <FilterEmptyState filter={activeFilter} />}

        </div>
      )}

      {/* ── Bottom sheet: status changer ────────────────────────────── */}
      <BottomSheet open={!!sheetJob} onClose={closeSheet} title="Status ändern">
        {sheetJob && (
          <>
            <p className="text-[14px] font-medium text-[var(--color-fg)] truncate">{sheetJob.company || "Stelle"}</p>
            <p className="text-[12.5px] text-[var(--color-fg-muted)] truncate mt-0.5">{sheetJob.role || "-"}</p>
            <ul className="mt-4 flex flex-col">
              {STATUS_BUCKETS.map((b, i) => {
                const isCurrent = sheetJob.status === b.key;
                return (
                  <li key={b.key} className={i > 0 ? "border-t border-[var(--color-border-subtle)]" : ""}>
                    <button
                      type="button"
                      onClick={() => handleStatusPick(b.key)}
                      className="w-full flex items-center justify-between py-3.5 text-left hover:text-[var(--color-fg)] transition-colors"
                    >
                      <span className={`text-[14.5px] ${isCurrent ? "text-[var(--color-fg)] font-medium" : "text-[var(--color-fg-muted)]"}`}>
                        {b.label}
                      </span>
                      {isCurrent && <span className="text-[12px] text-[var(--color-fg-faint)]">aktuell</span>}
                    </button>
                  </li>
                );
              })}
              <li className="border-t border-[var(--color-border-subtle)]">
                <button
                  type="button"
                  onClick={handleToggleMute}
                  className="w-full flex items-center justify-between py-3.5 text-left hover:text-[var(--color-fg)] transition-colors"
                >
                  <span className="flex items-center gap-2 text-[14.5px] text-[var(--color-fg-muted)]">
                    <VolumeX className="w-3.5 h-3.5" />
                    {mutedIds.has(sheetJob.id) ? "Wiederaufnehmen" : "Parken"}
                  </span>
                </button>
              </li>
            </ul>
          </>
        )}
      </BottomSheet>
    </div>
  );
}

import { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import {
  Check, Star, Zap, Crown, Building2, ArrowRight, Loader2,
} from "lucide-react";
import toast from "react-hot-toast";

import { billingApi } from "../services/api";
import useAuthStore from "../hooks/useAuthStore";
import { getApiErrorMessage } from "../utils/apiError";
import LegalLayout from "../components/ui/LegalLayout";

const FEATURE_LABELS = {
  cv_analysis: "Lebenslauf-Analysen / Monat",
  cover_letter: "Motivationsschreiben / Monat",
  job_alerts: "Aktive Job-Alerts",
  ai_chat: "KI-Bewerbungsassistent / Monat",
  job_search: "Jobsuche / Tag",
};

/** Formats a plan limit for display; -1 means unbegrenzt. */
function formatLimit(value) {
  return value === -1 ? "Unbegrenzt" : value;
}

/** Purely presentational UI metadata keyed to plan keys. All business data
    (prices, limits) is fetched from the backend so there is one source of truth. */
const PLAN_UI = {
  basic: {
    subtitle: "Zum Ausprobieren",
    icon: Star,
    highlighted: false,
    badge: null,
    extras: ["Lebenslauf hochladen", "Job-Suche", "Pipeline-Tracking"],
  },
  pro: {
    subtitle: "Für aktive Bewerber",
    icon: Zap,
    highlighted: true,
    badge: "Beliebt",
    extras: ["Prioritäts-Support", "Alles aus Basic"],
  },
  max: {
    subtitle: "Unbegrenzte Power",
    icon: Crown,
    highlighted: false,
    badge: "Bestes Angebot",
    extras: ["24h Support", "Alles aus Pro", "Unbegrenzte Nutzung"],
  },
  enterprise: {
    subtitle: "Für Teams & Agenturen",
    icon: Building2,
    highlighted: false,
    badge: null,
    extras: ["Dedizierter Manager", "Custom Integrationen", "SLA & Compliance"],
  },
};

function usePlans() {
  return useQuery({
    queryKey: ["billing", "plans"],
    queryFn: async () => {
      const res = await billingApi.plans();
      return res.data;
    },
    staleTime: 5 * 60 * 1000, // 5 minutes
  });
}

/** Pricing page — 4 plan cards with upgrade CTAs through Stripe checkout. */
export default function PricingPage() {
  const navigate = useNavigate();
  const token = useAuthStore((s) => s.token);
  // Read the init cache populated by AppShell (no queryFn — cache-only).
  // Only enable when authenticated; otherwise there's no AppShell to seed it.
  const { data: initData } = useQuery({ queryKey: ["init"], enabled: false });
  const currentPlan = initData?.plan || "basic";
  const [loadingPlan, setLoadingPlan] = useState(null);
  const { data: plansData, isLoading: plansLoading, error: plansError } = usePlans();

  const plans = plansData ?? [];
  if (plansError) {
    // Non-blocking: we still render the layout even if the API flakes.
    // eslint-disable-next-line no-console
    console.error("Failed to load plans", plansError);
  }

  const handleUpgrade = async (planKey) => {
    if (!token) {
      navigate("/register");
      return;
    }

    if (planKey === "enterprise") {
      window.location.href = "mailto:jobassistsupport@gmail.com?subject=Enterprise-Anfrage";
      return;
    }

    setLoadingPlan(planKey);
    try {
      const res = await billingApi.createCheckout(planKey);
      window.location.href = res.data.checkout_url;
    } catch (err) {
      toast.error(getApiErrorMessage(err, "Fehler beim Starten des Checkout-Prozesses"));
      setLoadingPlan(null);
    }
  };

  return (
    <LegalLayout
      wide
      title={<>Starte kostenlos. <span className="font-display italic text-[var(--color-accent-300)]">Upgrade,</span> wann du willst.</>}
      subtitle="Alle Pläne ohne MwSt. · Jederzeit kündbar · Keine versteckten Kosten"
    >
      <div className="grid grid-cols-12 gap-5">
        {plansLoading && (
          <div className="col-span-12 flex items-center justify-center py-12 text-[var(--color-fg-muted)]">
            <Loader2 className="h-5 w-5 animate-spin mr-2" />
            Pläne werden geladen…
          </div>
        )}
        {!plansLoading && plans.map((plan) => {
          const ui = PLAN_UI[plan.key] || {};
          const Icon = ui.icon || Star;
          const isCurrent = currentPlan === plan.key;
          const isHighlighted = ui.highlighted;

          return (
            <div
              key={plan.key}
              className={`group col-span-12 sm:col-span-6 lg:col-span-3 relative flex flex-col rounded-2xl border p-7 transition-all duration-200 hover:-translate-y-1 hover:shadow-[0_12px_40px_-12px_rgba(124,92,255,0.45)] ${
                isHighlighted
                  ? "border-[var(--color-accent-500)]/50 bg-[var(--color-bg-elev-1)]"
                  : "border-[var(--color-border)] bg-[var(--color-bg-elev-1)]/60 hover:border-[var(--color-accent-500)]/40"
              }`}
            >
              {ui.badge && (
                <div className="absolute -top-3 left-1/2 -translate-x-1/2">
                  <span
                    className={`rounded-full px-3 py-0.5 text-[10px] font-bold uppercase tracking-wider shadow-md ${
                      isHighlighted
                        ? "bg-[var(--color-accent-500)] text-white"
                        : "bg-[var(--color-bg-elev-2)] text-[var(--color-accent-300)] border border-[var(--color-accent-500)]/30"
                    }`}
                  >
                    {ui.badge}
                  </span>
                </div>
              )}

              <div className="flex items-center gap-3 mb-5">
                <div
                  className={`grid h-10 w-10 place-items-center rounded-xl ${
                    isHighlighted ? "bg-[var(--color-accent-500)]/15" : "bg-[var(--color-bg-elev-2)]"
                  }`}
                >
                  <Icon
                    className={`h-4.5 w-4.5 ${
                      isHighlighted ? "text-[var(--color-accent-300)]" : "text-[var(--color-fg-muted)]"
                    }`}
                  />
                </div>
                <div>
                  <h3 className="text-[16px] font-semibold text-[var(--color-fg)] leading-tight">{plan.name}</h3>
                  <p className="text-[11px] text-[var(--color-fg-muted)]">{ui.subtitle}</p>
                </div>
              </div>

              <div className="mb-5">
                {plan.price !== null ? (
                  <div className="flex items-baseline gap-1.5">
                    <span className="text-[34px] font-bold tracking-tight tabular-nums text-[var(--color-fg)] leading-none">
                      {plan.price === 0 ? "Gratis" : `€${String(plan.price).replace(".", ",")}`}
                    </span>
                    {plan.price !== 0 && (
                      <span className="text-[12px] font-medium text-[var(--color-fg-muted)]">/ Monat</span>
                    )}
                  </div>
                ) : (
                  <span className="text-[22px] font-semibold text-[var(--color-fg)]">Auf Anfrage</span>
                )}
              </div>

              <div className="h-px bg-[var(--color-border-subtle)] mb-4" />

              <ul className="flex-1 space-y-3 mb-6">
                {Object.entries(plan.limits).map(([feature, value]) => (
                  <li key={feature} className="flex items-start gap-2.5 text-[13px] leading-snug">
                    <Check className="h-3.5 w-3.5 mt-0.5 flex-shrink-0 text-[var(--color-accent-300)]" />
                    <span className="min-w-0">
                      <span className="font-semibold text-[var(--color-fg)]">{formatLimit(value)}</span>{" "}
                      <span className="text-[var(--color-fg-muted)]">{FEATURE_LABELS[feature]}</span>
                    </span>
                  </li>
                ))}
                {ui.extras?.map((extra) => (
                  <li key={extra} className="flex items-start gap-2.5 text-[13px] leading-snug">
                    <Check className="h-3.5 w-3.5 mt-0.5 flex-shrink-0 text-[var(--color-fg-dim)]" />
                    <span className="min-w-0 text-[var(--color-fg-muted)]">{extra}</span>
                  </li>
                ))}
              </ul>

              {isCurrent ? (
                <button
                  disabled
                  className="w-full cursor-not-allowed rounded-lg border border-[var(--color-accent-500)]/30 bg-[var(--color-accent-500)]/10 py-2.5 text-[13px] font-semibold text-[var(--color-accent-300)]"
                >
                  Aktueller Plan
                </button>
              ) : plan.key === "basic" ? (
                <button
                  disabled
                  className="w-full rounded-lg border border-[var(--color-border)] bg-[var(--color-bg-elev-1)] py-2.5 text-[13px] font-semibold text-[var(--color-fg-dim)] cursor-not-allowed"
                >
                  Inklusive
                </button>
              ) : (
                <button
                  onClick={() => handleUpgrade(plan.key)}
                  disabled={loadingPlan === plan.key}
                  className={`w-full inline-flex items-center justify-center gap-1.5 rounded-lg py-2.5 text-[13px] font-semibold transition-colors disabled:opacity-60 disabled:cursor-not-allowed ${
                    isHighlighted || plan.key === "max"
                      ? "bg-[var(--color-accent-500)] text-white hover:bg-[var(--color-accent-400)]"
                      : "border border-[var(--color-border)] bg-[var(--color-bg-elev-1)] text-[var(--color-fg)] hover:bg-[var(--color-bg-elev-2)]"
                  }`}
                >
                  {loadingPlan === plan.key ? (
                    <>
                      <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      Wird geladen…
                    </>
                  ) : (
                    <>
                      {plan.key === "enterprise" ? "Kontakt aufnehmen" : "Plan wählen"}
                      <ArrowRight className="h-3.5 w-3.5" />
                    </>
                  )}
                </button>
              )}
            </div>
          );
        })}
      </div>

      {/* Tiny reassurance + FAQ pointers */}
      <div className="mt-6 grid grid-cols-12 gap-3">
        {[
          { t: "Jederzeit kündbar",   d: "Monatliche Abrechnung. Kein Lock-in, keine Vertragsbindung." },
